{
  "description": "The creature is a single chimeric quadruped shown in right-facing profile walking forward. It has the overall size, proportions, dense shaggy brown fur, and limbs of a brown bear, but its back is covered from the nape to the rump by a large, highly glossy, hard, reddish-brown beetle carapace, and a single large, curved, glossy dark horn rises from its forehead. The fur is light tan on the muzzle and face, medium brown on the body, and darker brown on the lower legs, with a thick ruff around the neck and shoulders. The beetle shell is domed and smooth with fine longitudinal ridges and appears fused to the dorsal midline, giving the animal a bear-beetle hybrid appearance.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head at the anterior end, covered in brown fur with a lighter tan muzzle, a large black nose at the tip, small dark brown eyes on the sides, and fine whiskers on the muzzle",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "one large, glossy, dark reddish-brown to black, sickle-shaped horn with two small pointed tines on its inner curve, smooth and curved upward and backward to a sharp tip",
      "where": "arising from the center of the forehead just between and in front of the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, densely furred ears with brown fur, slightly lighter inside",
      "where": "on the top of the head behind the horn, one more forward and one slightly behind"
    },
    {
      "part": "mane/ruff",
      "looks_like": "thick, long, shaggy brown fur forming a dense ruff around the neck and shoulders, slightly darker and longer than the body fur",
      "where": "encircling the neck and extending onto the chest and shoulders just in front of the shell"
    },
    {
      "part": "legs",
      "looks_like": "four stout, heavily muscled, densely furred legs with shaggy brown fur, darker toward the lower portion, two forelegs and two hindlegs",
      "where": "under the body supporting it, forelegs under the chest and hindlegs under the hips, in mid-stride"
    },
    {
      "part": "feet",
      "looks_like": "four broad bear paws with visible dark claws on the toes, the soles and claws in contact with or lifted just above the ground",
      "where": "at the distal ends of each leg"
    },
    {
      "part": "tail",
      "looks_like": "very short, stubby, fur-covered tail with brown fur, barely protruding",
      "where": "at the posterior end of the body, just below the rear edge of the shell on the left side of the image"
    },
    {
      "part": "shell",
      "looks_like": "large, domed, extremely glossy and smooth hard shell in dark reddish-brown with lighter reflective highlights, with fine longitudinal striations and tiny dark speckles",
      "where": "covering the entire dorsal surface from just behind the ears and ruff to just above the tail"
    },
    {
      "part": "plates",
      "looks_like": "the shell is divided into two major plates: a smaller anterior pronotal plate over the shoulders that is more vaulted and rounded, and a larger posterior elytral plate over the back that is oval and ridged, separated by a narrow dark joint; the ventral margin has a serrated edge with a row of small circular openings",
      "where": "on the back, the anterior plate sits over the shoulder region and the posterior plate extends over the mid-back to the hindquarters"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
